/* @autogenerated */
package net.civeira.phylax.common.security;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.mockStatic;

import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.MockedStatic;

@DisplayName("SecureTokenService without SHA-256")
class SecureTokenServiceHashFailureUnitTest {

  @Test
  @DisplayName("Should report a missing SHA-256 provider as an illegal state")
  void shouldWrapMissingSha256() {
    SecureTokenService service = new SecureTokenService();
    try (MockedStatic<MessageDigest> digest = mockStatic(MessageDigest.class)) {
      digest.when(() -> MessageDigest.getInstance(anyString()))
          .thenThrow(new NoSuchAlgorithmException("missing"));
      IllegalStateException ex =
          assertThrows(IllegalStateException.class, () -> service.hash("token"));
      assertEquals("SHA-256 not available", ex.getMessage());
    }
  }
}
